B.cXa=new A.dr("Nenhum documento a caducar nos pr\xf3ximos 12 meses.",!1,null,null)
B.cXb=new A.dr("Dica: num dos bancos com cart\xf5es virtuais, crie um cart\xe3o s\xf3 para subscri\xe7\xf5es e mude as cobran\xe7as para l\xe1.",!1,null,null)
B.cXc=new A.dr("N\xe3o encontrei lan\xe7amentos suspeitos.",!1,null,null)
